    foreach ($extraLang in @($extra.Keys)) {
        if ($null -eq $overlays[$extraLang]) { $overlays[$extraLang] = @{} }
        foreach ($extraKey in @($extra[$extraLang].Keys)) {
            $overlays[$extraLang][$extraKey] = $extra[$extraLang][$extraKey]
        }
    }
    foreach ($extraLang in @($extraDetail.Keys)) {
        if ($null -eq $overlays[$extraLang]) { $overlays[$extraLang] = @{} }
        foreach ($extraKey in @($extraDetail[$extraLang].Keys)) {
            $overlays[$extraLang][$extraKey] = $extraDetail[$extraLang][$extraKey]
        }
    }
    foreach ($extraLang in @($featureExtra.Keys)) {
        if ($null -eq $overlays[$extraLang]) { $overlays[$extraLang] = @{} }
        foreach ($extraKey in @($featureExtra[$extraLang].Keys)) {
            $overlays[$extraLang][$extraKey] = $featureExtra[$extraLang][$extraKey]
        }
    }

    $overlay = $overlays[$lang]
    if ($null -eq $overlay) { return $english }
    $merged = @{}
    foreach ($key in $english.Keys) { $merged[$key] = $english[$key] }
    foreach ($key in $overlay.Keys) { $merged[$key] = $overlay[$key] }
    return $merged
}
